{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2173-11-24 11:00:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee, one of the surgical team. I understand you’ve been having ongoing pain with your G-tube. Can you tell me more about it?"
    },
    {
      "turn_number": 2,
      "time": "2173-11-24 11:01:00",
      "speaker": "Patient",
      "text": "Yes, it’s been really bothering me. The tube pulled at some point, and the pain never went away. It’s constant around the site."
    },
    {
      "turn_number": 3,
      "time": "2173-11-24 11:02:00",
      "speaker": "Doctor",
      "text": "I see. You’ve had several G-tubes placed before, and this one is in your remnant stomach. We discussed re-siting the tube, and you’ve decided to go ahead with that today."
    },
    {
      "turn_number": 4,
      "time": "2173-11-24 11:03:00",
      "speaker": "Patient",
      "text": "Yes, I don’t want more major surgery like revising the bypass or dealing with the pancreas. I just want the tube moved to stop the pain."
    },
    {
      "turn_number": 5,
      "time": "2173-11-24 11:04:00",
      "speaker": "Doctor",
      "text": "That makes sense. The plan is to remove the current tube and place a new one surgically through an open procedure. It’s low risk, and we expect good relief."
    },
    {
      "turn_number": 6,
      "time": "2173-11-24 11:05:00",
      "speaker": "Patient",
      "text": "Will I be asleep? I’m a little nervous about that."
    },
    {
      "turn_number": 7,
      "time": "2173-11-24 11:06:00",
      "speaker": "Doctor",
      "text": "Yes, you’ll be fully under general anesthesia. The anesthesia team will monitor you closely the whole time."
    },
    {
      "turn_number": 8,
      "time": "2173-11-24 11:07:00",
      "speaker": "Patient",
      "text": "Okay, that’s good to hear."
    },
    {
      "turn_number": 9,
      "time": "2173-11-24 12:00:00",
      "speaker": "Doctor",
      "text": "Just updating you — you’ve just come out of surgery. The open G-tube replacement went smoothly. No complications. You’re in the recovery area now."
    },
    {
      "turn_number": 10,
      "time": "2173-11-24 12:01:00",
      "speaker": "Patient",
      "text": "Oh, already? I didn’t feel a thing. Is the new tube in?"
    },
    {
      "turn_number": 11,
      "time": "2173-11-24 12:02:00",
      "speaker": "Doctor",
      "text": "Yes, the new tube is securely placed in a better location. You’ll stay on pain medication through the tube for now."
    },
    {
      "turn_number": 12,
      "time": "2173-11-24 12:03:00",
      "speaker": "Patient",
      "text": "Will it hurt when I wake up?"
    },
    {
      "turn_number": 13,
      "time": "2173-11-24 12:04:00",
      "speaker": "Doctor",
      "text": "You’ll have some discomfort, but we’re using a PCA pump at first, then switch to Dilaudid tablets through the tube. Pain should be well controlled."
    },
    {
      "turn_number": 14,
      "time": "2173-11-24 14:30:00",
      "speaker": "Doctor",
      "text": "How’s the pain now? On a scale of 1 to 10?"
    },
    {
      "turn_number": 15,
      "time": "2173-11-24 14:31:00",
      "speaker": "Patient",
      "text": "Maybe a 5. It’s sore, but not sharp. Better than before."
    },
    {
      "turn_number": 16,
      "time": "2173-11-24 14:32:00",
      "speaker": "Doctor",
      "text": "Good. That’s expected. You’re doing well — heart rate and breathing are stable. We’ll keep watching you tonight."
    },
    {
      "turn_number": 17,
      "time": "2173-11-24 14:33:00",
      "speaker": "Patient",
      "text": "Can I drink water yet?"
    },
    {
      "turn_number": 18,
      "time": "2173-11-24 14:34:00",
      "speaker": "Doctor",
      "text": "Not yet. You’ll stay NPO tonight. We’ll start tube feeds tomorrow once we’re sure everything is healing."
    },
    {
      "turn_number": 19,
      "time": "2173-11-25 08:00:00",
      "speaker": "Doctor",
      "text": "Morning. Your labs look good — no signs of infection or bleeding. We’re going to start your tube feeds today at a low rate."
    },
    {
      "turn_number": 20,
      "time": "2173-11-25 08:01:00",
      "speaker": "Patient",
      "text": "That’s great. I was worried about not eating."
    },
    {
      "turn_number": 21,
      "time": "2173-11-25 08:02:00",
      "speaker": "Doctor",
      "text": "You’re getting nutrition through the new tube. We’ll ramp up slowly to your usual 65 mL/hour. You’ll stay on Dilaudid for pain as needed."
    },
    {
      "turn_number": 22,
      "time": "2173-11-25 08:03:00",
      "speaker": "Patient",
      "text": "And my other meds? Like fluoxetine and pantoprazole?"
    },
    {
      "turn_number": 23,
      "time": "2173-11-25 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll crush all your pills and give them through the G-tube once you’re tolerating feeds. No NSAIDs — you’re allergic, remember?"
    },
    {
      "turn_number": 24,
      "time": "2173-11-25 08:05:00",
      "speaker": "Patient",
      "text": "Right, no ibuprofen. I’ll stick to acetaminophen."
    },
    {
      "turn_number": 25,
      "time": "2173-11-25 13:00:00",
      "speaker": "Doctor",
      "text": "Your MRSA screen came back — no MRSA detected. That’s excellent. Means lower infection risk."
    },
    {
      "turn_number": 26,
      "time": "2173-11-25 13:01:00",
      "speaker": "Patient",
      "text": "I had it before, so I was worried. Good to hear."
    },
    {
      "turn_number": 27,
      "time": "2173-11-26 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing really well. Pain is down, you’re tolerating full feeds at 65 mL/hour, and you walked in the hall this morning."
    },
    {
      "turn_number": 28,
      "time": "2173-11-26 09:01:00",
      "speaker": "Patient",
      "text": "The pain is maybe a 2 now. And I feel stronger walking."
    },
    {
      "turn_number": 29,
      "time": "2173-11-26 09:02:00",
      "speaker": "Doctor",
      "text": "Perfect. We’ll keep encouraging movement to prevent clots. You’re on heparin shots and compression boots for that."
    },
    {
      "turn_number": 30,
      "time": "2173-11-26 09:03:00",
      "speaker": "Patient",
      "text": "Is the wound healing okay?"
    },
    {
      "turn_number": 31,
      "time": "2173-11-26 09:04:00",
      "speaker": "Doctor",
      "text": "Yes, the incision is clean, no redness or drainage. You’ll have a nurse come daily to change the dressing at home."
    },
    {
      "turn_number": 32,
      "time": "2173-11-27 10:00:00",
      "speaker": "Doctor",
      "text": "Another good night. You’re afebrile, pain is controlled, and you’re passing gas — all signs your gut is working normally."
    },
    {
      "turn_number": 33,
      "time": "2173-11-27 10:01:00",
      "speaker": "Patient",
      "text": "Can I have a little water by mouth?"
    },
    {
      "turn_number": 34,
      "time": "2173-11-27 10:02:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll let you sip water. But keep all nutrition through the tube. No solid food by mouth."
    },
    {
      "turn_number": 35,
      "time": "2173-11-27 10:03:00",
      "speaker": "Patient",
      "text": "Got it. And my meds — I need to crush them?"
    },
    {
      "turn_number": 36,
      "time": "2173-11-27 10:04:00",
      "speaker": "Doctor",
      "text": "Exactly. Crush all pills and mix with water before flushing through the tube. That’s critical."
    },
    {
      "turn_number": 37,
      "time": "2173-11-27 14:00:00",
      "speaker": "Doctor",
      "text": "We’re planning to discharge you tomorrow. You’re stable, ambulating, and tolerating everything well."
    },
    {
      "turn_number": 38,
      "time": "2173-11-27 14:01:00",
      "speaker": "Patient",
      "text": "That’s great. What do I need to watch for at home?"
    },
    {
      "turn_number": 39,
      "time": "2173-11-27 14:02:00",
      "speaker": "Doctor",
      "text": "Call us if you get a fever over 101.5, severe pain, redness or pus from the wound, or can’t keep feeds running."
    },
    {
      "turn_number": 40,
      "time": "2173-11-27 14:03:00",
      "speaker": "Patient",
      "text": "And pain meds? I have the Dilaudid?"
    },
    {
      "turn_number": 41,
      "time": "2173-11-27 14:04:00",
      "speaker": "Doctor",
      "text": "Yes, you’ll get Dilaudid for breakthrough pain. It can make you drowsy, so no driving or heavy lifting over 10 pounds for six weeks."
    },
    {
      "turn_number": 42,
      "time": "2173-11-27 14:05:00",
      "speaker": "Patient",
      "text": "I’ll have help at home. The nurse will come daily?"
    },
    {
      "turn_number": 43,
      "time": "2173-11-27 14:06:00",
      "speaker": "Doctor",
      "text": "Yes, a nurse will visit daily for dressing changes. Keep the site clean and dry. You can shower, but no baths or swimming."
    },
    {
      "turn_number": 44,
      "time": "2173-11-28 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Final check — you’re afebrile, pain is mild, and you’re eating and drinking small amounts safely."
    },
    {
      "turn_number": 45,
      "time": "2173-11-28 09:01:00",
      "speaker": "Patient",
      "text": "I feel ready to go home. Thank you."
    },
    {
      "turn_number": 46,
      "time": "2173-11-28 09:02:00",
      "speaker": "Doctor",
      "text": "You’re doing great. Discharge meds include acetaminophen, Dilaudid, and stool softeners for constipation."
    },
    {
      "turn_number": 47,
      "time": "2173-11-28 09:03:00",
      "speaker": "Patient",
      "text": "I’ll take Colace twice a day, right?"
    },
    {
      "turn_number": 48,
      "time": "2173-11-28 09:04:00",
      "speaker": "Doctor",
      "text": "Yes, and bisacodyl if needed. Keep up the fluids and movement. Follow up with your surgeon in one week."
    },
    {
      "turn_number": 49,
      "time": "2173-11-28 09:05:00",
      "speaker": "Patient",
      "text": "And no NSAIDs — I remember."
    },
    {
      "turn_number": 50,
      "time": "2173-11-28 09:06:00",
      "speaker": "Doctor",
      "text": "Exactly. You’ve got it. We’ll get the discharge papers ready. You should be home within a few hours."
    },
    {
      "turn_number": 51,
      "time": "2173-11-28 10:30:00",
      "speaker": "Doctor",
      "text": "Just confirming — you understand to crush all pills and give via G-tube?"
    },
    {
      "turn_number": 52,
      "time": "2173-11-28 10:31:00",
      "speaker": "Patient",
      "text": "Yes, I’ll crush them and flush well."
    },
    {
      "turn_number": 53,
      "time": "2173-11-28 10:32:00",
      "speaker": "Doctor",
      "text": "And if the tube clogs?"
    },
    {
      "turn_number": 54,
      "time": "2173-11-28 10:33:00",
      "speaker": "Patient",
      "text": "Flush with warm water, and if it doesn’t clear, call the nurse or doctor."
    },
    {
      "turn_number": 55,
      "time": "2173-11-28 10:34:00",
      "speaker": "Doctor",
      "text": "Perfect. You’re all set. We’re discharging you with home health support. Take care."
    },
    {
      "turn_number": 56,
      "time": "2173-11-28 10:35:00",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee. I’m so glad the pain is gone."
    },
    {
      "turn_number": 57,
      "time": "2173-11-28 11:00:00",
      "speaker": "Doctor",
      "text": "One last thing — your tube feeds should stay at 65 mL/hour continuously. Don’t adjust the rate unless instructed."
    },
    {
      "turn_number": 58,
      "time": "2173-11-28 11:01:00",
      "speaker": "Patient",
      "text": "Got it. Nutrihep at 65 mL/hour, same as before."
    },
    {
      "turn_number": 59,
      "time": "2173-11-28 11:02:00",
      "speaker": "Doctor",
      "text": "Correct. And keep taking pantoprazole and rifaximin as prescribed — they help with stomach acid and gut bacteria."
    },
    {
      "turn_number": 60,
      "time": "2173-11-28 11:03:00",
      "speaker": "Patient",
      "text": "I won’t forget. I’ve been on them a long time."
    },
    {
      "turn_number": 61,
      "time": "2173-11-28 11:04:00",
      "speaker": "Doctor",
      "text": "Good. Also, your depression and anxiety meds — fluoxetine and zolpidem — keep those consistent."
    },
    {
      "turn_number": 62,
      "time": "2173-11-28 11:05:00",
      "speaker": "Patient",
      "text": "Yes, I take fluoxetine three times a day and zolpidem at night."
    },
    {
      "turn_number": 63,
      "time": "2173-11-28 11:06:00",
      "speaker": "Doctor",
      "text": "Right. And clonidine patch once a week. All these go through the G-tube, crushed or dissolved."
    },
    {
      "turn_number": 64,
      "time": "2173-11-28 11:07:00",
      "speaker": "Patient",
      "text": "I’ll make sure my caregiver knows the routine."
    },
    {
      "turn_number": 65,
      "time": "2173-11-28 11:08:00",
      "speaker": "Doctor",
      "text": "Excellent. You’re well prepared. We’ll see you in follow-up, but call sooner if anything concerns you."
    },
    {
      "turn_number": 66,
      "time": "2173-11-28 11:09:00",
      "speaker": "Patient",
      "text": "I will. Thanks again for fixing the tube."
    },
    {
      "turn_number": 67,
      "time": "2173-11-28 11:10:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take it easy, and we’ll check in soon."
    }
  ],
  "summary": {
    "admission_start": "2173-11-24 10:30:00",
    "admission_end": "2173-11-28 15:47:00",
    "summary_paragraph": "The patient was admitted for chronic G-tube site pain due to mechanical pulling of the tube, which failed to resolve with prior interventions. She underwent an open gastrostomy tube replacement without complications. Postoperatively, she remained stable, afebrile, and alert, with good pain control managed initially with PCA and transitioned to oral Dilaudid via G-tube. Tube feeds were restarted on postoperative day 2 and advanced to her prior rate of 65 mL/hour, which she tolerated well. She resumed sipping water, ambulated early, and had no signs of infection or bleeding. A MRSA screen was negative. She was discharged home with home health services for wound care, instructions to crush all medications and administer via G-tube, and clear guidance on activity restrictions, diet, and warning signs. Follow-up was arranged with her surgeon.",
    "problems": [
      "Other gastrostomy complications",
      "Polycystic ovaries",
      "Other specified procedures as the cause of abnormal reaction of patient, or of later complication, without mention of misadventure at time of procedure",
      "Accidents occurring in residential institution",
      "Bariatric surgery status"
    ]
  }
}
